/* Power9 Desk Reset — local, dependency-free Lab 2 prototype. */
const root = document.getElementById('app');
const DAY = 'Thứ Tư, 14/10/2026';
const baseHabits = () => [
  {id:'shoulder',name:'Thả lỏng vai và cổ',principle:'Downshift',time:'14:15',duration:4,days:['T2','T3','T4','T5','T6'],done:false,reminder:true},
  {id:'walk',name:'Đi bộ quanh văn phòng',principle:'Move Naturally',time:'15:30',duration:8,days:['T2','T3','T4','T5','T6'],done:false,reminder:true}
];
const model={screen:'login',stack:[],habits:baseHabits(),activeId:'shoulder',mode:'create',draft:null,selectedTime:null,modal:null,toast:'',report:'idle',reportRange:'week',reminders:true,notificationRead:false,filter:'all',editorError:'',flow:'f1',loading:false,epoch:0,editorErrors:{},saveError:'',rescheduleUndo:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const habit=()=>model.habits.find(h=>h.id===model.activeId);
const countDone=()=>model.habits.filter(h=>h.done).length;
const weekMinutes=()=>28+model.habits.filter(h=>h.done).reduce((sum,h)=>sum+h.duration,0);
const nextHabit=()=>[...model.habits].filter(h=>!h.done).sort((a,b)=>(a.todayTime||a.time).localeCompare(b.todayTime||b.time))[0];
const cancelPending=()=>{model.epoch++;model.loading=false;if(model.report==='loading')model.report='idle';};
const later=(callback,delay)=>{const epoch=model.epoch;setTimeout(()=>{if(epoch===model.epoch)callback();},delay);};
const hasNav=()=>['home','library','progress','profile'].includes(model.screen);
const nav=(active)=>`<nav class="bottom-nav" aria-label="Điều hướng chính">${[
  ['home','⌂','Hôm nay'],['library','◈','Thư viện'],['progress','▥','Tiến độ'],['profile','●','Cá nhân']
].map(([id,icon,label])=>`<button class="nav-item ${active===id?'active':''}" data-action="nav" data-target="${id}" type="button" ${active===id?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('')}</nav>`;
const topBar=(title,back=true,right='')=>`<header class="topbar"><div class="top-actions">${back?'<button class="icon-button" data-action="back" type="button" aria-label="Quay lại">←</button>':''}<h2>${title}</h2></div><div class="top-actions">${right}</div></header>`;
const screen=(body,{title='',back=false,right='',navActive='',footer='',dark=false}={})=>`<div class="screen ${dark?'dark':''}">${title?topBar(title,back,right):''}<div class="scroll ${navActive?'with-nav':''}">${body}</div>${footer}${navActive?nav(navActive):''}</div>`;
const btn=(label,action,kind='button full',extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const toast=()=>model.toast?`<div role="status" class="toast ${hasNav()?'':'no-nav'}">${esc(model.toast)}${model.rescheduleUndo?'<button type="button" data-action="undo-reschedule" class="toast-undo">Hoàn tác dời giờ</button>':''}</div>`:'';
const modal=()=>{if(!model.modal)return '';const m=model.modal;return `<div class="dialog-scrim" role="presentation"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h3 id="dialog-title">${esc(m.title)}</h3><p>${esc(m.text)}</p><div class="button-row">${btn('Hủy','close-modal','button ghost')}${btn(esc(m.confirm),'confirm-modal',`button ${m.danger?'danger':''}`)}</div></div></div>`};
function render(){const ui=captureUI();let html='';switch(model.screen){case 'login':html=renderLogin();break;case 'home':html=renderHome();break;case 'library':html=renderLibrary();break;case 'principle':html=renderPrinciple();break;case 'editor':html=renderEditor();break;case 'detail':html=renderDetail();break;case 'progress':html=renderProgress();break;case 'reports':html=renderReports();break;case 'profile':html=renderProfile();break;case 'notifications':html=renderNotifications();break;default:html=renderHome()};root.innerHTML=html+toast()+modal();restoreUI(ui);}
function notify(message,keepUndo=false){if(!keepUndo)model.rescheduleUndo=null;model.toast=message;render();clearTimeout(notify.timer);notify.timer=setTimeout(()=>{model.toast='';model.rescheduleUndo=null;render()},7000)}
function go(screen){cancelPending();if(model.screen!==screen)model.stack.push(model.screen);model.screen=screen;model.toast='';render()}
function back(){cancelPending();if(model.modal){model.modal=null;render();return}if(model.screen==='reports'&&model.report==='viewer'){model.report='ready';render();return}if(model.screen==='editor'&&model.draft&&model.draft.changed){model.modal={type:'discard',title:'Bỏ thay đổi?',text:'Lịch vừa chỉnh chưa được lưu. Bạn có thể tiếp tục sửa hoặc bỏ các thay đổi.',confirm:'Bỏ thay đổi'};render();return}model.screen=model.stack.pop()||'home';model.toast='';render()}
function reset(flow){cancelPending();clearTimeout(notify.timer);model.editorErrors={};model.saveError='';model.rescheduleUndo=null;model.flow=flow;model.habits=baseHabits();model.stack=[];model.activeId='shoulder';model.mode='create';model.draft=null;model.selectedTime=null;model.modal=null;model.toast='';model.report='idle';model.reportRange='week';model.reminders=true;model.notificationRead=false;model.filter='all';model.editorError='';model.loading=false;model.screen=flow==='f1'?'login':'home';render()}
function renderLogin(){return `<div class="screen dark"><div class="login-wrap"><div class="login-icon">9</div><p class="eyebrow">POWER9 / DESK RESET</p><h1>Cho ngày làm việc<br>có khoảng thở.</h1><p>Những nhịp nghỉ ngắn có thể đổi lịch theo cuộc họp. Bắt đầu với một thói quen vừa sức.</p><div class="login-panel"><strong>Hôm nay của Huy</strong><p>Họp nhóm 09:00 · Sprint review 14:00. App sẽ gợi ý khung giờ trống để nghỉ và vận động.</p></div><div class="login-bottom">${btn(model.loading?'Đang mở lịch…':'Bắt đầu với dữ liệu demo','login','button full',model.loading?'disabled':'')}<small>Prototype chỉ lưu trạng thái trong phiên xem. Không kết nối tài khoản thật.</small></div></div></div>`}
function renderHome(){if(!model.habits.length)return screen(`<p class="kicker">${DAY}</p><div class="empty"><span class="symbol">◌</span><h3>Chưa có khoảng nghỉ hôm nay</h3><p>Thêm một hoạt động Power9 ngắn để bắt đầu lịch làm việc linh hoạt.</p>${btn("+ Khám phá gợi ý Power9","open-library","button")}</div>`,{title:"Hôm nay",right:`<button class="icon-button" data-action="open-notifications" type="button" aria-label="Thông báo">♧</button>`,navActive:"home"});const next=nextHabit();const right=`<button class="icon-button" data-action="open-notifications" type="button" aria-label="Thông báo">♧${model.notificationRead?'':'<span class="dot"></span>'}</button>`;const events=[{type:'meeting',time:'09:00',title:'Họp nhóm',end:'10:00'},{type:'meeting',time:'14:00',title:'Sprint review',end:'15:00'},...model.habits.map(h=>({type:'habit',time:h.todayTime||h.time,habit:h}))].sort((a,b)=>a.time.localeCompare(b.time));return screen(`<p class="kicker">${DAY}</p><div class="hero"><small>Chào Huy, lịch làm việc hôm nay</small><h2>${next?'Một khoảng nghỉ đang chờ bạn.':'Bạn đã hoàn thành lịch nghỉ.'}</h2><div class="hero-time">${next?`${esc(next.todayTime||next.time)} · ${esc(next.duration)} phút`:`${model.habits.length} khoảng nghỉ đã xong`}</div><p>${next?'Có họp bất ngờ? Dời lịch ngay trên thẻ hoạt động.':'Xem lại tiến độ để giữ nhịp tuần này.'}</p>${next?'<button class="hero-cta" data-action="open-next" type="button">Xem hoạt động tiếp theo →</button>':'<button class="hero-cta" data-action="nav" data-target="progress" type="button">Xem tiến độ →</button>'}</div><div class="section-heading"><h3>Lịch theo giờ</h3><span>${countDone()}/${model.habits.length} hoàn thành</span></div><div class="agenda">${events.map(event=>event.type==='meeting'?`<div class="agenda-row"><div class="agenda-time">${event.time}</div><div class="agenda-card meeting"><div class="agenda-top"><strong>${event.title}</strong><span class="status-pill">Lịch làm việc</span></div><p>${event.time}–${event.end} · Đã có trên lịch</p></div></div>`:`<div class="agenda-row"><div class="agenda-time">${esc(event.time)}</div><div class="agenda-card ${event.habit.done?'checked':''}"><div class="agenda-top"><strong>${esc(event.habit.name)}</strong><span class="status-pill ${event.habit.done?'done':''}">${event.habit.done?'✓ Đã xong':`${event.habit.duration} phút`}</span></div><p>${esc(event.habit.principle)} · ${event.habit.reminder&&model.reminders?'Có nhắc':'Đã tắt nhắc'}${event.habit.todayTime?' · Đã dời hôm nay':''}</p><div class="row-actions"><button class="mini-button ${event.habit.done?'':'primary'}" type="button" data-action="${event.habit.done?'undo':'check'}" data-id="${event.habit.id}">${event.habit.done?'Hoàn tác':'✓ Hoàn thành'}</button><button class="mini-button" type="button" data-action="open-detail" data-id="${event.habit.id}">${event.habit.done?'Chi tiết':'Dời / sửa'}</button></div></div></div>`).join('')}</div><div class="note-strip"><span class="symbol">↗</span><div><strong>Đổi lịch theo cuộc họp</strong>Nếu lỡ một nhịp nghỉ, chọn giờ trống gần nhất thay vì bỏ cả ngày.</div></div><div class="section-heading"><h3>Thêm hoạt động</h3></div>${btn('+ Khám phá gợi ý Power9','open-library','button secondary full')}`,{title:'Hôm nay',right,navActive:'home'})}
function renderLibrary(){return screen(`<p class="kicker">CHỌN VIỆC NHỎ CHO NGÀY BẬN</p><h1 class="page-title">Thư viện Power9</h1><p class="lead">Ưu tiên mẫu có thể làm tại bàn hoặc trong một khoảng nghỉ ngắn.</p><div class="tabs"><button class="tab ${model.filter==='all'?'active':''}" data-action="filter" data-filter="all">Tất cả</button><button class="tab ${model.filter==='desk'?'active':''}" data-action="filter" data-filter="desk">Tại bàn</button><button class="tab ${model.filter==='walk'?'active':''}" data-action="filter" data-filter="walk">Rời màn hình</button></div>${model.filter!=='walk'?`<article class="card"><div class="card-head"><div><span class="flow-badge">DOWNSHIFT · TẠI BÀN</span><h3>Thở chậm 3 phút</h3></div><span class="status-pill">3 phút</span></div><p>Đặt một nhịp nghỉ ngắn sau cuộc họp để hạ nhịp căng thẳng.</p>${btn('Xem nguyên tắc →','open-principle','mini-button')}</article><article class="card"><div class="card-head"><div><span class="flow-badge">DOWNSHIFT · TẠI BÀN</span><h3>Thả lỏng vai và cổ</h3></div><span class="status-pill">4 phút</span></div><p>Động tác nhẹ không cần đổi chỗ, phù hợp giữa các phiên làm việc.</p>${btn('Đặt lịch từ mẫu','template-habit','mini-button','data-template="shoulder"')}</article>`:''}${model.filter!=='desk'?`<article class="card"><div class="card-head"><div><span class="flow-badge">MOVE NATURALLY</span><h3>Đi bộ quanh văn phòng</h3></div><span class="status-pill">8 phút</span></div><p>Rời màn hình và vận động nhẹ trong giờ nghỉ.</p>${btn('Đặt lịch từ mẫu','template-habit','mini-button','data-template="walk"')}</article>`:''}`,{title:'Thư viện',navActive:'library'})}
function renderPrinciple(){return screen(`<div class="detail-head"><span class="kicker">POWER9 / DOWNSHIFT</span><h2>Cho tâm trí một nhịp nghỉ.</h2><p>Downshift là gợi ý chủ động dành một khoảng dừng ngắn trong ngày. Desk Reset chuyển ý tưởng này thành một hoạt động dễ đặt vào lịch làm việc.</p></div><h3 class="section-heading">Mẫu phù hợp giờ làm</h3><article class="card"><div class="card-head"><h3>Thở chậm sau cuộc họp</h3><span class="status-pill">3 phút</span></div><p>Đề xuất 15:10, sau Sprint review. Có thể chọn giờ khác trước khi lưu.</p>${btn('Tạo từ mẫu này','new-habit','button full')}</article><div class="note-strip"><span class="symbol">i</span><div>Hoạt động chỉ là gợi ý sinh hoạt. Bạn có thể tắt nhắc hoặc thay đổi lịch bất cứ lúc nào.</div></div>`,{title:'Chi tiết nguyên tắc',back:true})}
function freshDraft(h){return {name:h?.name||'Thở chậm sau cuộc họp',principle:h?.principle||'Downshift',time:h?.time||'15:10',duration:h?.duration||3,days:[...(h?.days||['T2','T3','T4','T5','T6'])],reminder:h?.reminder??true,changed:false}}
function renderEditor(){const d=model.draft||freshDraft();const edit=model.mode==='edit';const errors=model.editorErrors;const fieldError=(key)=>errors[key]?`<small id="${key}-error" class="error-text">${esc(errors[key])}</small>`:'';return screen(`<p class="kicker">${edit?'ĐIỀU CHỈNH THÓI QUEN':'TẠO TỪ GỢI Ý'}</p><h1 class="page-title">${edit?'Sửa lịch nghỉ':'Đặt một khoảng nghỉ'}</h1><p class="lead">Lịch linh hoạt: chọn giờ thuận tiện giữa các cuộc họp.</p>${model.saveError?`<p class="error-banner" role="alert">${esc(model.saveError)}</p>`:''}<form id="habit-form" novalidate><div class="field"><label for="habit-name">Tên hoạt động *</label><input id="habit-name" name="name" maxlength="50" value="${esc(d.name)}" aria-invalid="${!!errors.name}" ${errors.name?'aria-describedby="name-error"':''} autocomplete="off" required>${fieldError('name')}</div><div class="field"><label for="habit-principle">Nguyên tắc Power9</label><select id="habit-principle" name="principle"><option ${d.principle==='Downshift'?'selected':''}>Downshift</option><option ${d.principle==='Move Naturally'?'selected':''}>Move Naturally</option></select></div><div class="button-row"><div class="field"><label for="habit-time">Giờ thực hiện *</label><input id="habit-time" name="time" type="time" value="${esc(d.time)}" required aria-invalid="${!!errors.time}" ${errors.time?'aria-describedby="time-error"':''}>${fieldError('time')}</div><div class="field"><label for="habit-duration">Số phút *</label><input id="habit-duration" name="duration" type="number" min="1" max="120" step="1" value="${esc(d.duration)}" required aria-invalid="${!!errors.duration}" ${errors.duration?'aria-describedby="duration-error"':''}>${fieldError('duration')}</div></div><fieldset class="field day-field" id="habit-days" ${errors.days?'aria-describedby="days-error" aria-invalid="true"':''}><legend>Ngày trong tuần *</legend><div class="chips">${['T2','T3','T4','T5','T6','T7','CN'].map(day=>`<button type="button" class="chip ${d.days.includes(day)?'selected':''}" data-action="toggle-day" data-day="${day}" aria-pressed="${d.days.includes(day)}">${day}</button>`).join('')}</div>${fieldError('days')}<small>Tối thiểu một ngày. Giờ nhắc chỉ áp dụng cho ngày đã chọn.</small></fieldset><div class="card switch-row"><div><strong>Nhắc trước giờ nghỉ</strong><small>Thông báo đưa thẳng tới hoạt động</small></div><button type="button" class="switch ${d.reminder?'on':''}" data-action="toggle-reminder" role="switch" aria-checked="${d.reminder}" aria-label="Nhắc trước giờ nghỉ"></button></div><div class="note-strip"><span class="symbol">◷</span><div>Giờ họp 14:00–15:00 đã được đánh dấu trong lịch. Hãy chọn một thời điểm khác nếu trùng họp.</div></div></form>${model.loading?'<div class="note-strip" role="status">Đang lưu lịch nghỉ…</div>':''}`,{title:edit?'Sửa thói quen':'Thêm thói quen',back:true,footer:`<div class="sticky-actions"><button type="submit" form="habit-form" class="button full" ${model.loading?'disabled aria-busy="true"':''}>${model.loading?'Đang lưu…':edit?'Lưu thay đổi':'Lưu thói quen'}</button></div>`})}
function renderDetail(){const h=habit();if(!h)return screen(`<div class="empty"><h3>Hoạt động không còn</h3><p>Thói quen này đã bị xóa. Về Hôm nay để xem lịch hiện tại.</p>${btn('Về Hôm nay','home','button')}</div>`,{title:'Chi tiết hoạt động',back:true});const shownTime=h.todayTime||h.time;const isConflict=shownTime>='14:00'&&shownTime<'15:00';return screen(`<div class="detail-head"><span class="kicker">${esc(h.principle.toUpperCase())}</span><h2>${esc(h.name)}</h2><p>Hôm nay ${esc(shownTime)} · ${h.duration} phút · ${h.days.join(', ')} · ${h.reminder&&model.reminders?'Có nhắc':'Đã tắt nhắc'}</p><p class="recurring-time">Lịch lặp: ${esc(h.time)} · ${esc(h.days.join(', '))}${h.todayTime?' · Không đổi':''}</p></div><div class="card"><div class="card-head"><h3>Hôm nay</h3><span class="status-pill ${h.done?'done':'warning'}">${h.done?'✓ Đã hoàn thành':'Chưa thực hiện'}</span></div><p>${h.done?'Đã ghi nhận hoạt động hôm nay. Bạn có thể hoàn tác nếu bấm nhầm.':'Hoàn thành khi bạn đã thực hiện xong, hoặc dời lịch nếu giờ này không phù hợp.'}</p><div class="button-row">${btn(h.done?'Hoàn tác':'✓ Hoàn thành',h.done?'undo-active':'check-active','button secondary')}${btn('Sửa chi tiết','edit-habit','button ghost')}</div></div><div class="section-heading"><h3>Dời nhanh hôm nay</h3><span>Chỉ hôm nay</span></div><p class="small muted">Chọn giờ trống sau cuộc họp. Lịch lặp của những ngày sau vẫn giữ nguyên; sửa chi tiết nếu muốn đổi lâu dài.</p>${isConflict?'<div class="note-strip"><span class="symbol">!</span><div>Giờ hiện tại trùng Sprint review 14:00–15:00.</div></div>':''}<div class="quick-times"><button class="quick-time ${model.selectedTime==='15:40'?'selected':''}" data-action="choose-time" data-time="15:40" type="button" aria-pressed="${model.selectedTime==='15:40'}">15:40<small>Sau Sprint review</small></button><button class="quick-time ${model.selectedTime==='16:10'?'selected':''}" data-action="choose-time" data-time="16:10" type="button" aria-pressed="${model.selectedTime==='16:10'}">16:10<small>Trước khi kết thúc ngày</small></button></div><div style="margin-top:11px">${btn(model.selectedTime?`Xác nhận dời sang ${model.selectedTime}`:'Chọn giờ để dời','confirm-time','button full',model.selectedTime?'':'disabled')}</div><hr class="divider"><button class="text-button" data-action="delete-habit" type="button" style="color:#a52b2b">Xóa thói quen này</button>`,{title:'Chi tiết hoạt động',back:true})}
function renderProgress(){
 const done=countDone();const monthly=model.reportRange==='month';const values=monthly?[4,3,3+done,0]:[2,1,1+done,0,0,0,0];const labels=monthly?['Tuần 1','Tuần 2','Tuần 3','Tuần 4']:['T2','T3','T4','T5','T6','T7','CN'];const total=(monthly?10:4)+done;const minutes=(monthly?70:28)+model.habits.filter(h=>h.done).reduce((sum,h)=>sum+h.duration,0);
 const content=model.reportRange==='empty'?`<div class="empty"><h3>Chưa có dữ liệu trong khoảng này</h3><p>Chọn Tuần này để xem những hoạt động đã ghi nhận.</p>${btn('Xem tuần này','range-week','button secondary')}</div>`:`<div class="stat-grid"><div class="stat"><b>${total}</b><span>lần nghỉ đã ghi nhận</span></div><div class="stat"><b>${minutes}</b><span>phút vận động và thư giãn</span></div></div><article class="card" style="margin-top:12px"><h3>${monthly?'Theo tuần trong tháng':'Nhịp trong tuần'}</h3><p>Số liệu minh họa, cộng thêm lần ghi nhận trong phiên demo.</p><div class="timeline-bars" role="img" aria-label="${esc(values.map((v,i)=>labels[i]+': '+v+' lần').join('; '))}">${values.map((n,i)=>`<div class="bar-col" aria-hidden="true"><b>${n}</b><div class="bar" style="height:${Math.max(4,n*18)}px"></div><small>${labels[i]}</small></div>`).join('')}</div><p class="small">${total} lần · ${monthly?'Tháng 10/2026':'Tuần 12–18/10/2026'}. Hôm nay ${done}/${model.habits.length} hoạt động hoàn thành.</p></article>${btn('Tạo báo cáo tuần này →','open-reports','button full')}`;
 return screen(`<p class="kicker">THEO DÕI NHỊP NGHỈ</p><h1 class="page-title">Tiến độ</h1><p class="lead">Số liệu minh họa, không phải đánh giá sức khỏe.</p><div class="tabs" role="group" aria-label="Khoảng thời gian">${[['week','Tuần này'],['month','Tháng này'],['empty','Khoảng trống']].map(([id,label])=>`<button class="tab ${model.reportRange===id?'active':''}" data-action="range" data-range="${id}" aria-pressed="${model.reportRange===id}">${label}</button>`).join('')}</div>${content}`,{title:'Tiến độ',navActive:'progress'});
}
function renderReports(){const status=model.report;let body=`<p class="kicker">BÁO CÁO HOẠT ĐỘNG</p><h1 class="page-title">Tổng kết nhịp nghỉ</h1><p class="lead">Khoảng ngày 12–18/10/2026 · chỉ gồm các hoạt động đã ghi nhận.</p>`;if(status==='idle')body+=`<article class="card"><h3>Sẵn sàng tạo bản xem</h3><p>Thông tin mẫu cho buổi demo. Không tạo PDF hoặc tải dữ liệu lên mạng.</p></article>${btn('Tạo báo cáo','generate-report','button full')}`;if(status==='loading')body+=`<div class="empty" role="status"><span class="symbol">◌</span><h3>Đang chuẩn bị báo cáo…</h3><p>Vui lòng chờ trong giây lát.</p></div>`;if(status==='error')body+=`<div class="empty" role="alert"><span class="symbol">!</span><h3>Chưa tạo được báo cáo</h3><p>Khoảng ngày của bạn vẫn được giữ. Thử lại để tiếp tục.</p>${btn('Thử lại','generate-report','button secondary')}</div>`;if(status==='ready')body+=`<div class="empty" role="status"><span class="symbol">✓</span><h3>Báo cáo đã sẵn sàng</h3><p>Bản xem minh họa của tuần 12–18/10/2026.</p>${btn('Mở bản xem','view-report','button')}</div>`;if(status==='viewer')body+=`<div class="report-sheet"><span class="flow-badge">POWER9 DESK RESET · BẢN XEM</span><h3>Tuần 12–18/10/2026</h3><div class="report-number">${4+countDone()} lần</div><p>Hoạt động đã ghi nhận trong tuần. Tổng thời gian minh họa: ${weekMinutes()} phút.</p><hr class="divider"><p><strong>Nhận xét:</strong> Các khoảng nghỉ ngắn dễ sắp xếp hơn sau giờ họp. Tiếp tục điều chỉnh lịch theo thực tế.</p></div>`;return screen(body,{title:'Báo cáo',back:true})}
function renderProfile(){return screen(`<p class="kicker">CÀI ĐẶT CÁ NHÂN</p><h1 class="page-title">Chào Huy</h1><p class="lead">Bản demo cho nhân viên văn phòng. Cài đặt chỉ tồn tại trong phiên xem prototype.</p><div class="card"><div class="switch-row"><div><strong>Nhắc nghỉ trong ngày làm việc</strong><small>${model.reminders?'Đang bật':'Đang tắt'} · có thể chỉnh từng hoạt động</small></div><button class="switch ${model.reminders?'on':''}" data-action="toggle-profile-reminder" type="button" role="switch" aria-checked="${model.reminders}" aria-label="Nhắc nghỉ trong ngày làm việc"></button></div></div><div class="card"><h3>Khung giờ làm việc</h3><p>Thứ Hai–Thứ Sáu · 09:00–17:30</p><p style="margin-top:7px">Lịch họp minh họa: 09:00–10:00, 14:00–15:00</p></div>${btn('Lưu cài đặt','save-profile','button full')}<div class="section-heading"><h3>Khác</h3></div><div class="card" style="padding:0"><button class="list-row" type="button" data-action="open-notifications"><span><strong>Thông báo</strong><small>Xem nhắc nghỉ và lịch đã thay đổi</small></span><span class="arrow">›</span></button><button class="list-row" type="button" data-action="logout"><span><strong>Đăng xuất</strong><small>Quay về màn giới thiệu</small></span><span class="arrow">›</span></button></div>`,{title:'Cá nhân',navActive:'profile'})}
function renderNotifications(){const h=model.habits.find(x=>x.id==='shoulder');return screen(`<p class="kicker">LỜI NHẮC CÓ NGỮ CẢNH</p><h1 class="page-title">Thông báo</h1><p class="lead">Mở đúng hoạt động từ lời nhắc, rồi chọn giờ phù hợp với lịch họp.</p>${h?`<button class="list-row notification ${model.notificationRead?'read':''}" type="button" data-action="notification-detail" data-id="shoulder" style="border-radius:14px;margin-bottom:12px"><span><strong>${model.notificationRead?'Đã đọc':'Chưa đọc'} · Giờ nghỉ cần điều chỉnh</strong><small>Thả lỏng vai và cổ · ${esc(h.todayTime||h.time)}. Có thể dời sang sau cuộc họp.</small></span><span class="arrow">›</span></button>`:`<div class="empty"><h3>Hoạt động đã được xóa</h3><p>Lời nhắc cũ không còn đích mở. Về Hôm nay để xem lịch hiện tại.</p>${btn('Về Hôm nay','home','button secondary')}</div>`}<button class="list-row notification read" type="button" data-action="notification-walk" style="border-radius:14px"><span><strong>Đã đọc · Đi bộ quanh văn phòng</strong><small>15:30 · 8 phút · Mở hoạt động</small></span><span class="arrow">›</span></button>`,{title:'Thông báo',back:true})}
function captureDraft(){if(model.screen!=='editor')return;const form=document.getElementById('habit-form');if(!form)return;model.draft.name=form.elements.name.value;model.draft.principle=form.elements.principle.value;model.draft.time=form.elements.time.value;model.draft.duration=Number(form.elements.duration.value);}
function validateDraft(d){
 const errors={};
 if(!d.name.trim())errors.name='Nhập tên hoạt động để tiếp tục.';
 else if(d.name.trim().length>50)errors.name='Tên hoạt động tối đa 50 ký tự.';
 if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(d.time))errors.time='Chọn một giờ hợp lệ.';
 if(!Number.isInteger(d.duration)||d.duration<1||d.duration>120)errors.duration='Nhập số phút nguyên từ 1 đến 120.';
 if(!d.days.length)errors.days='Chọn ít nhất một ngày trong tuần.';
 return errors;
}
function saveHabit(simulateError=false){
 if(model.loading||model.screen!=='editor')return;
 captureDraft();const d=model.draft;model.editorErrors=validateDraft(d);model.saveError='';
 const first=Object.keys(model.editorErrors)[0];
 if(first){render();const target=first==='days'?root.querySelector('[data-action="toggle-day"]'):document.getElementById('habit-'+first);target?.focus();return;}
 if(simulateError){model.saveError='Chưa lưu được. Dữ liệu nhập vẫn còn; hãy thử lưu lại.';render();return;}
 model.loading=true;render();
 later(()=>{const clean={name:d.name.trim(),principle:d.principle,time:d.time,duration:d.duration,days:[...d.days],reminder:d.reminder};
  if(model.mode==='create'){const id='habit-'+Date.now()+'-'+model.habits.length;model.habits.push({...clean,id,done:false});model.activeId=id;}
  else {const existing=habit();if(!existing){model.loading=false;notify('Hoạt động không còn để chỉnh sửa.');return;}Object.assign(existing,clean);}
  model.loading=false;model.draft=null;model.selectedTime=null;model.screen='detail';model.stack=['home'];notify('✓ Đã lưu thói quen và cập nhật lịch.');
 },650);
}
root.addEventListener('input',e=>{if(model.screen==='editor'&&e.target.closest('#habit-form')){captureDraft();model.draft.changed=true;model.editorError=''}});
root.addEventListener('submit',e=>{if(e.target.id==='habit-form'){e.preventDefault();saveHabit()}});
root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;const id=el.dataset.id;if(a==='back'){back();return}if(a==='nav'){cancelPending();model.stack=[];model.screen=el.dataset.target;render();return}if(a==='home'){cancelPending();model.stack=[];model.screen='home';render();return}if(a==='login'){model.loading=true;render();later(()=>{model.loading=false;model.screen='home';render()},550);return}if(a==='open-library'){go('library');return}if(a==='open-principle'){go('principle');return}if(a==='template-habit'){model.mode='create';model.draft=freshDraft(el.dataset.template==='walk'?{name:'Đi bộ quanh văn phòng',principle:'Move Naturally',time:'15:30',duration:8}:baseHabits()[0]);model.editorErrors={};model.saveError='';go('editor');return}if(a==='new-habit'){model.mode='create';model.draft=freshDraft();model.editorError='';model.editorErrors={};model.saveError='';go('editor');return}if(a==='open-next'){const h=nextHabit();if(h){model.activeId=h.id;model.selectedTime=null;go('detail')}return}if(a==='open-detail'){model.activeId=id;model.selectedTime=null;go('detail');return}if(a==='check'||a==='undo'){const h=model.habits.find(x=>x.id===id);if(h){h.done=a==='check';notify(h.done?'✓ Đã ghi nhận. Tiến độ hôm nay đã cập nhật.':'Đã hoàn tác lần ghi nhận này.')}return}if(a==='check-active'||a==='undo-active'){const h=habit();h.done=a==='check-active';notify(h.done?'✓ Đã ghi nhận hoạt động hôm nay.':'Đã hoàn tác lần ghi nhận này.');return}if(a==='choose-time'){model.selectedTime=el.dataset.time;render();return}if(a==='confirm-time'){if(!model.selectedTime||!habit())return;const h=habit();model.rescheduleUndo={id:h.id,previous:h.todayTime};h.todayTime=model.selectedTime;model.selectedTime=null;model.screen='home';model.stack=[];notify(`✓ Đã dời hôm nay sang ${h.todayTime}. Lịch lặp ${h.time} không đổi.`,true);return}if(a==='undo-reschedule'){const undo=model.rescheduleUndo;const h=model.habits.find(x=>x.id===undo?.id);if(h)h.todayTime=undo.previous;notify('Đã hoàn tác dời giờ hôm nay.');return}if(a==='edit-habit'){model.mode='edit';model.draft=freshDraft(habit());model.editorError='';model.editorErrors={};model.saveError='';go('editor');return}if(a==='toggle-day'){captureDraft();const day=el.dataset.day;const i=model.draft.days.indexOf(day);if(i<0)model.draft.days.push(day);else model.draft.days.splice(i,1);model.draft.changed=true;render();return}if(a==='toggle-reminder'){captureDraft();model.draft.reminder=!model.draft.reminder;model.draft.changed=true;render();return}if(a==='save-habit'){saveHabit();return}if(a==='simulate-save-error'){saveHabit(true);return}if(a==='filter'){model.filter=el.dataset.filter;render();return}if(a==='range'){model.reportRange=el.dataset.range;render();return}if(a==='range-week'){model.reportRange='week';render();return}if(a==='open-reports'){model.report='idle';go('reports');return}if(a==='generate-report'){model.report='loading';render();later(()=>{model.report='ready';render()},700);return}if(a==='report-error'){model.report='error';render();return}if(a==='view-report'){model.report='viewer';render();return}if(a==='toggle-profile-reminder'){model.reminders=!model.reminders;render();return}if(a==='save-profile'){notify('✓ Đã lưu cài đặt lời nhắc.');return}if(a==='open-notifications'){go('notifications');return}if(a==='notification-detail'){model.notificationRead=true;model.activeId=id;model.selectedTime=null;go('detail');return}if(a==='notification-walk'){model.activeId='walk';model.selectedTime=null;go('detail');return}if(a==='delete-habit'){model.modal={type:'delete',title:'Xóa thói quen?',text:`Xóa “${habit().name}” khỏi lịch? Dữ liệu của hoạt động này sẽ không còn trong bản demo.`,confirm:'Xóa hoạt động',danger:true};render();return}if(a==='logout'){model.modal={type:'logout',title:'Đăng xuất?',text:'Bạn sẽ quay về màn giới thiệu. Bản demo có thể bắt đầu lại từ các luồng bên trái.',confirm:'Đăng xuất'};render();return}if(a==='close-modal'){model.modal=null;render();return}if(a==='confirm-modal'){const type=model.modal?.type;model.modal=null;if(type==='delete'){model.habits=model.habits.filter(h=>h.id!==model.activeId);model.screen='home';model.stack=[];notify('Đã xóa hoạt động khỏi lịch.');return}if(type==='logout'){model.screen='login';model.stack=[];render();return}if(type==='discard'){model.draft=null;model.screen=model.stack.pop()||'home';render();return}}});
let renderedScreen='',renderedModal=false,modalReturnKey=null;
function focusKey(el){if(!el||!root.contains(el))return null;return {id:el.id,action:el.dataset?.action,target:el.dataset?.target,day:el.dataset?.day,time:el.dataset?.time,item:el.dataset?.id,filter:el.dataset?.filter,range:el.dataset?.range};}
function findFocus(key){if(!key)return null;if(key.id)return document.getElementById(key.id);return [...root.querySelectorAll('[data-action]')].find(el=>el.dataset.action===key.action&&el.dataset.target===key.target&&el.dataset.day===key.day&&el.dataset.time===key.time&&el.dataset.id===key.item&&el.dataset.filter===key.filter&&el.dataset.range===key.range);}
function captureUI(){return {focus:focusKey(document.activeElement),scroll:root.querySelector('.scroll')?.scrollTop||0,same:renderedScreen===model.screen,hadModal:renderedModal};}
function restoreUI(ui){const main=root.querySelector('.screen');if(main)main.inert=!!model.modal;
 if(ui.same){const scroll=root.querySelector('.scroll');if(scroll)scroll.scrollTop=ui.scroll;}
 if(model.modal){if(!ui.hadModal)modalReturnKey=ui.focus;root.querySelector('.dialog button')?.focus();}
 else {const target=ui.hadModal?findFocus(modalReturnKey):ui.same?findFocus(ui.focus):null;
  if(target)target.focus({preventScroll:true});else if(!ui.same||ui.hadModal){const heading=root.querySelector('h1,h2,h3');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}}
 renderedScreen=model.screen;renderedModal=!!model.modal;
}
root.addEventListener('keydown',e=>{if(!model.modal)return;if(e.key==='Escape'){e.preventDefault();model.modal=null;render();return;}if(e.key==='Tab'){const buttons=[...root.querySelectorAll('.dialog button:not([disabled])')];const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('click',e=>{const control=e.target.closest('[data-demo]');if(!control)return;const kind=control.dataset.demo;
 if(kind==='save-error'){if(model.screen!=='editor'){model.mode='create';model.draft=freshDraft();model.editorErrors={};go('editor');}saveHabit(true);}
 if(kind==='report-error'){model.report='error';go('reports');}
 if(kind==='empty-home'){model.habits=[];go('home');}
 if(kind==='missing-target'){model.habits=model.habits.filter(h=>h.id!=='shoulder');go('notifications');}
});
document.addEventListener('click',e=>{const flow=e.target.closest('[data-flow]');if(flow)reset(flow.dataset.flow)});
render();




